"27102": {"tmdb_id": 27102, "imdb_id": "tt0087821", "title": "Full Moon in Paris", "original_title": "Les Nuits de la pleine lune", "year": 1984, "directors": ["Éric Rohmer"], "countries": ["FR"], "runtime": 102, "cast": ["Pascale Ogier", "Tchéky Karyo", "Fabrice Luchini", "Virginie Thévenet", "Christian Vadim", "Szabó László"], "overview": "Feeling suffocated by a possessive boyfriend, work and suburban life, a young woman starts spending the weekends in her Paris apartment in order to reclaim some of her lost freedom.", "poster": "https://image.tmdb.org/t/p/w342/5HQU7dfVnB8HHRkdZzo1hV724gs.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/9RKsW96d3D93Z96HE46j7Pz5nlA.jpg"},
"27130": {"tmdb_id": 27130, "imdb_id": "tt0036027", "title": "I Walked with a Zombie", "original_title": "I Walked with a Zombie", "year": 1943, "directors": ["Jacques Tourneur"], "countries": ["US"], "runtime": 69, "cast": ["James Ellison", "Frances Dee", "Tom Conway", "Edith Barrett", "James Bell", "Christine Gordon"], "overview": "A nurse in the Caribbean turns to voodoo in hopes of curing her patient, a mindless woman whose husband she's fallen in love with.", "poster": "https://image.tmdb.org/t/p/w342/uoyBR8XNxPQRojujtczfG1qJezY.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/bCyK6eETwA6kzxLxDDuwJ3l7Wdw.jpg"},
"27145": {"tmdb_id": 27145, "imdb_id": "tt0080728", "title": "The Aviator's Wife", "original_title": "La Femme de l'aviateur", "year": 1981, "directors": ["Éric Rohmer"], "countries": ["FR"], "runtime": 106, "cast": ["Philippe Marlaud", "Marie Rivière", "Anne-Laure Meury", "Mathieu Carrière", "Philippe Caroit", "Coralie Clément"], "overview": "A student is devastated when he finds that his girlfriend is cheating on him. In order to find out why she did it, he decides to spy on her and her airline pilot lover. Then he sees the pilot with a blonde woman and he begins to follow them…", "poster": "https://image.tmdb.org/t/p/w342/xgXj1Fcgq1nHjhj9i7BiqvZarn5.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/lkS9SAwibcNK3CUYmtVk1cuOsg0.jpg"},
