"27327": {"tmdb_id": 27327, "imdb_id": "tt0071994", "title": "Phantom of the Paradise", "original_title": "Phantom of the Paradise", "year": 1974, "directors": ["Brian De Palma"], "countries": ["US"], "runtime": 92, "cast": ["William Finley", "Paul Williams", "Jessica Harper", "George Memmoli", "Gerrit Graham", "Archie Hahn"], "overview": "Singer-songwriter Winslow Leach seeks revenge on the nefarious music producer Swan, who steals both Winslow's music and his favorite singer for the grand opening of Swan's new rock palace, the Paradise.", "poster": "https://image.tmdb.org/t/p/w342/qDOtGWeSQNwB3dG7Amt1K0JW0az.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/mO5rgg8mr4fUIMrZykwP2MjPVmZ.jpg"},
"27375": {"tmdb_id": 27375, "imdb_id": "tt0064921", "title": "Salesman", "original_title": "Salesman", "year": 1969, "directors": ["David Maysles", "Charlotte Zwerin", "Albert Maysles"], "countries": ["US"], "runtime": 90, "cast": ["Paul Brennan", "Charles McDevitt", "James Baker", "Raymond Martos", "Melbourne I. Feltman", "Margaret McCarron"], "overview": "This documentary from Albert and David Maysles follows the bitter rivalry of four door-to-door salesmen working for the Mid-American Bible Company: Paul \"The Badger\" Brennan, Charles \"The Gipper\" McDevitt, James \"The Rabbit\" Baker and Raymond \"The Bull\" Martos. Times are tough for this hard-living quartet, who spend their days traveling through small-town America, trying their best to peddle gold-leaf Bibles to an apathetic crowd of lower-middle-class housewives and elderly couples.", "poster": "https://image.tmdb.org/t/p/w342/gQhe7uWygmAiQ6HNA7Jeys4wdbk.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/y9I304YATiOlL0EFCfTZ0b592kE.jpg"},
"27381": {"tmdb_id": 27381, "imdb_id": "tt0104511", "title": "Innocent Blood", "original_title": "Innocent Blood", "year": 1992, "directors": ["John Landis"], "countries": ["US"], "runtime": 112, "cast": ["Anne Parillaud", "David Proval", "Rocco Sisto", "Chazz Palminteri", "Anthony LaPaglia", "Robert Loggia"], "overview": "Marie is a vampire with a thirst for bad guys. When she fails to properly dispose of one of her victims, a violent mob boss, she bites off more than she can chew and faces a new, immortal danger.", "poster": "https://image.tmdb.org/t/p/w342/bloBdkHtAHSAJWa31Gls59z0xfb.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/8MAiMQLDfyd6YktQFk1B1bhzzz3.jpg"},
