"28276": {"tmdb_id": 28276, "imdb_id": "tt0053134", "title": "Good Morning", "original_title": "お早よう", "year": 1959, "directors": ["Yasujirō Ozu"], "countries": ["JP"], "runtime": 94, "cast": ["Keiji Sada", "Yoshiko Kuga", "Chishū Ryū", "Kuniko Miyake", "Haruko Sugimura", "Kōji Shitara"], "overview": "Two boys beg their parents for a television set, nagging them until all patience is lost. The parents order the boys to be quiet and the boys do exactly that--refusing to utter a word. The boys' silence ultimately puts the whole neighborhood into turmoil.", "poster": "https://image.tmdb.org/t/p/w342/dXy2LFsE0VlHlHJU3SLBdJgrzEq.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/qH9wiXnx9mU9kNGCH1exaey9CqU.jpg"},
