"28973": {"tmdb_id": 28973, "imdb_id": "tt0050598", "title": "A King in New York", "original_title": "A King in New York", "year": 1957, "directors": ["Charlie Chaplin"], "countries": ["GB", "US"], "runtime": 104, "cast": ["Charlie Chaplin", "Maxine Audley", "Jerry Desmonde", "Oliver Johnston", "Dawn Addams", "Sidney James"], "overview": "A recently-deposed \"Estrovian\" monarch seeks shelter in New York City, where he becomes an accidental television celebrity. Later, he's wrongly accused of being a Communist and gets caught up in subsequent HUAC hearings.", "poster": "https://image.tmdb.org/t/p/w342/e6KtBoiXa5D3LLZtiMCkiqIDnZv.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/wO62WckgbBMpu3efEIY9oQsSLb0.jpg"},
"28974": {"tmdb_id": 28974, "imdb_id": "tt0014624", "title": "A Woman of Paris: A Drama of Fate", "original_title": "A Woman of Paris: A Drama of Fate", "year": 1923, "directors": ["Charlie Chaplin"], "countries": ["US"], "runtime": 82, "cast": ["Edna Purviance", "Clarence Geldart", "Carl Miller", "Lydia Knott", "Charles K. French", "Adolphe Menjou"], "overview": "When Marie St. Clair believes she has been jilted by her artist fiance Jean, she decides to leave for Paris on her own. After spending a year in the city as a mistress of the wealthy Pierre Revel, she is reunited with Jean by chance. This leaves her with the choice between a glamorous life in Paris, and the true love she left behind.", "poster": "https://image.tmdb.org/t/p/w342/shmnpKWwfgNzntaDLPO0WYli5PX.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/oxhJn3vjqzzWrfwZpA2YgGkRpwi.jpg"},
