"1000517": {"tmdb_id": 1000517, "imdb_id": "tt21163478", "title": "The Temple Woods Gang", "original_title": "Le Gang des bois du temple", "year": 2022, "directors": ["Rabah Ameur-Zaïmeche"], "countries": ["FR"], "runtime": 116, "cast": ["Régis Laroche", "Marie Loustalot", "Philippe Petit", "Kenji Meunier", "Salim Ameur-Zaïmeche", "Kamel Mezdour"], "overview": "A retired military man lives in the Temple Woods housing project. Just as he’s burying his mother, his neighbour Bébé, who belongs to a gang of robbers from the area, is preparing to rob the convoy of a wealthy Arab prince.", "poster": "https://image.tmdb.org/t/p/w342/vopTdljiK7sUj92PWkMan6ruDE3.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/tni11mZ88b7mDLEb1TbKnVCxLMR.jpg"},
"1001434": {"tmdb_id": 1001434, "imdb_id": "tt30797042", "title": "This Life of Mine", "original_title": "Ma vie ma gueule", "year": 2024, "directors": ["Sophie Fillières"], "countries": ["FR"], "runtime": 99, "cast": ["Agnès Jaoui", "Philippe Katerine", "Édouard Sulpice", "Angelina Woreth", "Valérie Donzelli", "Emmanuel Salinger"], "overview": "Barbie, once an attractive, devoted mother and partner, faces newfound challenges as she turns 55, descending into darkness, violence, and absurdity while grappling with her identity, relationships, and life's complexities.", "poster": "https://image.tmdb.org/t/p/w342/HvF1s0vvXw305kReDobAvYhaGQ.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/gWyMVLs7YrzRaLWzP9jrSO1Tp1x.jpg"},
